static void FlecsGeneratedBody_Query_run_optional_2ff45fce() {
    flecs::world world;
	RegisterFlecsGeneratedTestTypes_66c939fe99(world);

    world.component<Position>();
    world.component<Velocity>();
    flecs::component<Mass>(world, "Mass");

    auto e1 = world.entity()
        .set<Position>({10, 20})
        .set<Velocity>({1, 2})
        .set<Mass>({1});

    auto e2 = world.entity()
        .set<Position>({30, 40})
        .set<Velocity>({3, 4})
        .set<Mass>({1});        

    auto e3 = world.entity()
        .set<Position>({50, 60});

    auto e4 = world.entity()
        .set<Position>({70, 80});

    auto q = world.query<Position, Velocity*, Mass*>();

    q.run([](flecs::iter& it) {
        while (it.next()) {
            auto p = it.field<Position>(0);
            auto v = it.field<Velocity>(1);
            auto m = it.field<Mass>(2);

            if (it.is_set(1) && it.is_set(2)) {
                for (auto i : it) {
                    p[i].x += v[i].x * m[i].value;
                    p[i].y += v[i].y * m[i].value;
                }
            } else {
                for (auto i : it) {
                    p[i].x ++;
                    p[i].y ++;
                }
            }
        }
    });

    const Position *p = e1.try_get<Position>();
    test_int(p->x, 11);
    test_int(p->y, 22);

    p = e2.try_get<Position>();
    test_int(p->x, 33);
    test_int(p->y, 44);

    p = e3.try_get<Position>();
    test_int(p->x, 51);
    test_int(p->y, 61);

    p = e4.try_get<Position>();
    test_int(p->x, 71);
    test_int(p->y, 81);
}

