static void FlecsGeneratedBody_Query_inspect_terms_w_each_b90a5e7f() {
    flecs::world world;
	RegisterFlecsGeneratedTestTypes_66c939fe99(world);

    auto p = world.entity();

    auto q = world.query_builder<Position>()
        .with<Velocity>()
        .with(flecs::ChildOf, p)
        .build();

    int32_t count =  0;
    q.each_term([&](flecs::term& t) {
        if (count == 0) {
            test_int(t.id(), world.id<Position>());
            test_int(t.inout(), flecs::InOutDefault);
        } else if (count == 1) {
            test_int(t.id(), world.id<Velocity>());
            test_int(t.inout(), flecs::InOutDefault);
        } else if (count == 2) {
            test_int(t.id(), world.pair(flecs::ChildOf, p));
            test_assert(t.id().second() == p);
            test_int(t.inout(), flecs::InOutDefault);
        } else {
            test_assert(false);
        }

        test_int(t.oper(), flecs::And);

        count ++;
    });

    test_int(count, 3);
}

